<?php
namespace App\Service\HelloAsso;
use App\Entity\HelloAssoPayment;use App\Entity\Participant;use App\Entity\Subscription;use App\Enum\HelloAssoPaymentMatchStatusEnum as MS;use App\Enum\RegistrationStatusEnum;use App\Repository\HelloAssoPaymentRepository;use App\Repository\ParticipantRepository;use App\Repository\SubscriptionRepository;use Doctrine\DBAL\Exception\UniqueConstraintViolationException;use Doctrine\ORM\EntityManagerInterface;use Psr\Log\LoggerInterface;
final class HelloAssoPaymentProcessor{public function __construct(private EntityManagerInterface $em,private HelloAssoPaymentRepository $payments,private ParticipantRepository $participants,private SubscriptionRepository $subscriptions,private ParticipantIdentityMatcher $identity,private string $org,private string $formType,private string $formSlug,private LoggerInterface $logger){}public function process(HelloAssoWebhookPayload $p):?HelloAssoPayment{return $this->em->wrapInTransaction(fn()=> $this->doProcess($p));}public function reconcile(HelloAssoPayment $payment):HelloAssoPayment{$p=new HelloAssoWebhookPayload('Payment',$payment->getPaymentId()??'', $payment->getPaymentState(),$payment->getOrderId(),$payment->getOrganizationSlug(),$payment->getFormType(),$payment->getFormSlug(),$payment->getTierId(),$payment->getAmount(),null,$payment->getReceiptUrl(),$payment->getPayerEmail(),$payment->getPayerFirstname(),$payment->getPayerLastname(),[],[],$payment->getPayloadHash()??'',0,$payment->getTierId()!==null);return $this->em->wrapInTransaction(fn()=> $this->evaluate($payment,$p));}private function doProcess(HelloAssoWebhookPayload $p):?HelloAssoPayment{if(!in_array(strtolower($p->eventType),['order','payment'],true))return null;if(strcasecmp($p->eventType,'Order')===0){if($p->registrationCount===0){$this->logger->warning('HelloAsso Order without Registration item.', ['orderId'=>$p->orderId]);return null;}if($p->registrationCount>1){$this->logger->warning('HelloAsso Order with multiple Registration items.', ['orderId'=>$p->orderId]);foreach($p->paymentIds as $pid)$this->upsert($p,$pid,MS::MULTIPLE_REGISTRATIONS,'Order contains multiple Registration items.');return null;}if($p->paymentIds===[]){$this->logger->warning('HelloAsso Order without usable payment id.', ['orderId'=>$p->orderId]);return null;} $last=null;foreach($p->paymentIds as $pid)$last=$this->upsert($p,$pid);return $last;}if($p->paymentId==='')throw new \Symfony\Component\HttpKernel\Exception\BadRequestHttpException('Missing payment id.');return $this->upsert($p,$p->paymentId);}private function upsert(HelloAssoWebhookPayload $p,string $paymentId,?MS $forcedStatus=null,?string $reason=null):HelloAssoPayment{$payment=$this->payments->findOneBy(['paymentId'=>$paymentId])??(new HelloAssoPayment())->setPaymentId($paymentId);$same=$payment->getPayloadHash()===$p->payloadHash;$this->fill($payment,$p);if(!$p->isExpected($this->org,$this->formType,$this->formSlug)){$payment->setMatchStatus(MS::IGNORED)->setMismatchReason('Notification ignored: unexpected HelloAsso form.');$this->em->persist($payment);$this->em->flush();return $payment;}if($forcedStatus){$payment->setMatchStatus($forcedStatus)->setMismatchReason($reason);$this->em->persist($payment);$this->em->flush();return $payment;}if($same&&$payment->getMatchStatus()===MS::MATCHED)return $payment;try{$this->em->persist($payment);$this->evaluate($payment,$p);$this->em->flush();}catch(UniqueConstraintViolationException $exception){$this->em->clear();$existing=$this->payments->findOneBy(['paymentId'=>$paymentId]);if($existing instanceof HelloAssoPayment)return $existing;throw $exception;}return $payment;}private function evaluate(HelloAssoPayment $payment,HelloAssoWebhookPayload $p):HelloAssoPayment{$payment->setUpdatedAt(new \DateTimeImmutable());if($this->isRefunded($payment->getPaymentState())){$payment->setMatchStatus(MS::REFUNDED)->setProcessedAt(new \DateTimeImmutable());$part=$payment->getParticipant();if($part instanceof Participant&&$part->getRegistrationStatus()===RegistrationStatusEnum::PAID)$part->setRegistrationStatus(RegistrationStatusEnum::REFUNDED);return $payment;}if(strcasecmp((string)$payment->getPaymentState(),'Contested')===0)return $payment->setMatchStatus(MS::PENDING)->setMismatchReason('Payment is contested and requires manual review.');if(!$this->isSuccessful($payment->getPaymentState()))return $payment->setMatchStatus(MS::PENDING)->setMismatchReason('Payment state is not accepted for validation.');if($payment->getTierId()===null)return $payment->setMatchStatus(MS::PENDING)->setMismatchReason('Waiting for Order registration data.');$subscription=$this->findActiveSubscription($payment->getTierId());if(!$subscription)return $payment->setMatchStatus(MS::UNKNOWN_TIER)->setMismatchReason('No active subscription matches the HelloAsso tierId.');$participant=$payment->getParticipant()??$this->findParticipant($p,$payment);if(!$participant)return $payment->setMatchStatus(MS::UNMATCHED_PARTICIPANT)->setMismatchReason('No participant found from internal reference or HelloAsso email.');$payment->setParticipant($participant);$email=$p->effectiveEmail()??$payment->getPayerEmail();if(!$this->emailMatches($participant,$email)&&!$this->hasExactReference($participant,$p))return $payment->setMatchStatus(MS::IDENTITY_MISMATCH)->setMismatchReason('HelloAsso email does not match participant email.');if(!$this->identity->matches($participant,$p->effectiveFirstname()??$payment->getPayerFirstname(),$p->effectiveLastname()??$payment->getPayerLastname()))return $payment->setMatchStatus(MS::IDENTITY_MISMATCH)->setMismatchReason('HelloAsso firstname/lastname does not match participant identity.');$payment->setSubscription($subscription);if($participant->getRegistrationStatus()===RegistrationStatusEnum::PAID){$other=$this->payments->createQueryBuilder('h')->andWhere('h.participant = :p')->andWhere('h.matchStatus = :s')->andWhere('h.paymentId != :pid')->setParameter('p',$participant)->setParameter('s',MS::MATCHED)->setParameter('pid',$payment->getPaymentId())->setMaxResults(1)->getQuery()->getOneOrNullResult();if($other instanceof HelloAssoPayment)return $payment->setMatchStatus(MS::PAYMENT_CONFLICT)->setMismatchReason('Participant is already paid with another HelloAsso payment.');}else{$participant->setRegistrationStatus(RegistrationStatusEnum::PAID)->setSubscription($subscription);if($participant->getPaidAt()===null)$participant->setPaidAt(new \DateTimeImmutable());}$payment->setMatchStatus(MS::MATCHED)->setMismatchReason(null)->setProcessedAt(new \DateTimeImmutable());return $payment;}private function fill(HelloAssoPayment $h,HelloAssoWebhookPayload $p):void{foreach([['setOrderId',$p->orderId],['setOrganizationSlug',$p->organizationSlug],['setFormType',$p->formType],['setFormSlug',$p->formSlug],['setTierId',$p->tierId],['setPayerEmail',$p->effectiveEmail()??$p->payerEmail],['setPayerFirstname',$p->effectiveFirstname()??$p->payerFirstname],['setPayerLastname',$p->effectiveLastname()??$p->payerLastname],['setPaymentState',$p->paymentState],['setAmount',$p->amount],['setReceiptUrl',$p->receiptUrl],['setPayloadHash',$p->payloadHash]] as [$m,$v])if($v!==null)$h->$m($v);}private function findParticipant(HelloAssoWebhookPayload $p,HelloAssoPayment $payment):?Participant{foreach(array_merge(array_values($p->metadata),$p->customFieldValues) as $v){if(is_scalar($v)&&($x=$this->participants->findOneBy(['internalReference'=>(string)$v])))return $x;}foreach([$p->itemEmail,$p->firstEmailFromCustomFields(),$p->payerEmail,$payment->getPayerEmail()] as $email){if($email&&($x=$this->participants->findOneByEmail($email)))return $x;}return null;}private function hasExactReference(Participant $p,HelloAssoWebhookPayload $payload):bool{return in_array($p->getInternalReference(),array_map('strval',array_merge(array_values($payload->metadata),$payload->customFieldValues)),true);}private function emailMatches(Participant $p,?string $email):bool{return $email!==null&&mb_strtolower(trim($p->getEmail()??''))===mb_strtolower(trim($email));}private function findActiveSubscription(?string $tier):?Subscription{if(!$tier)return null;$s=$this->subscriptions->findOneByHelloAssoTierId($tier);return $s instanceof Subscription&&$s->isActive()?$s:null;}private function isSuccessful(?string $s):bool{return strcasecmp((string)$s,'Authorized')===0;}private function isRefunded(?string $s):bool{return strcasecmp((string)$s,'Refunded')===0;}}
